def get_S(k, n):
    S = 0
    for j in range(1, k+1):
        S += math.factorial(j) * (j**(n-1))
    return S

def check_n_possible(n):
    # For a given n, such an a exists iff S_k = sum_{j=1}^k j! j^{n-1}
    # satisfies S_k = m_k k! for some sequence of integers m_k.
    # This is equivalent to m_k = m_{k-1}/k + k^{n-1} being an integer for all k.
    # This is equivalent to a_k = a_{k-1}/k + k^{n-1} being an integer for all k.
    # This is equivalent to a_0 = c_k + m_k k! being a constant integer.
    # As we found, this is equivalent to c_k = -S_k % k! being eventually constant.
    c = []
    for k in range(1, 100):
        c.append((-get_S(k, n)) % math.factorial(k))

    for K in range(1, len(c)):
        if all(c[i] == c[K] for i in range(K, len(c))):
            return True, K
    return False, 0

for n in range(1, 10):
    res, K = check_n_possible(n)
    print(f"n={n}: eventual_constant={res}, K={K}")

def find_polynomial(n):
    # c_{n-1} = 1
    # c_{m-1} - \sum_{j=m}^{n-1} c_j \binom{j}{m} (-1)^{j-m} = 0 for m < n
    # c_{n-1} = 1
    c = [0] * n
    c[n-1] = 1
    for m in range(n-1, 0, -1):
        # coefficient of k^m is c_{m-1} - \sum_{j=m}^{n-1} c_j \binom{j}{m} (-1)^{j-m}
        # so c_{m-1} = \sum_{j=m}^{n-1} c_j \binom{j}{m} (-1)^{j-m}
        res = 0
        from math import comb
        for j in range(m, n):
            res += c[j] * comb(j, m) * ((-1)**(j-m))
        c[m-1] = res

    # Now check the constant term (m=0)
    # The constant term of k a_k - a_{k-1} is - \sum_{j=0}^{n-1} c_j (-1)^j
    const_term = 0
    for j in range(n):
        const_term -= c[j] * ((-1)**j)

    if const_term == 0:
        return c
    else:
        return None

for n in range(1, 11):
    res = find_polynomial(n)
    print(f"n={n}: {res}")
